<script setup lang="ts">import { reactive } from 'vue'; import type { RegraValidacao, TipoRegra } from '../../types'; import BaseButton from '../ui/BaseButton.vue'; const props = defineProps<{ initial?: Partial<RegraValidacao> }>(); const emit = defineEmits<{ save: [rule: Partial<RegraValidacao>]; cancel: [] }>(); const form = reactive({ nome: props.initial?.nome || '', tipo: props.initial?.tipo || 'campo_obrigatorio' as TipoRegra, campo: String(props.initial?.parametros?.campo || ''), regex: String(props.initial?.parametros?.regex || ''), min: Number(props.initial?.parametros?.min || 0), max: Number(props.initial?.parametros?.max || 10), expressao: String(props.initial?.parametros?.expressao || ''), campo_resultado: String(props.initial?.parametros?.campo_resultado || ''), tolerancia: Number(props.initial?.parametros?.tolerancia || 0), obrigatoria: props.initial?.obrigatoria ?? true }); function save() { const parametros: Record<string, unknown> = form.tipo === 'campo_obrigatorio' ? { campo: form.campo } : form.tipo === 'formato' ? { campo: form.campo, regex: form.regex } : form.tipo === 'intervalo' ? { campo: form.campo, min: form.min, max: form.max } : { expressao: form.expressao, campo_resultado: form.campo_resultado, tolerancia: form.tolerancia }; emit('save', { nome: form.nome, tipo: form.tipo, parametros, obrigatoria: form.obrigatoria }) }</script>
<template><form class="space-y-3" @submit.prevent="save"><label class="block text-sm font-medium">Nome<input v-model="form.nome" required class="mt-1 w-full rounded border p-2" /></label><label class="block text-sm font-medium">Tipo<select v-model="form.tipo" class="mt-1 w-full rounded border p-2"><option value="campo_obrigatorio">Campo obrigatório</option><option value="formato">Formato</option><option value="intervalo">Intervalo</option><option value="calculo">Cálculo</option></select></label><label v-if="form.tipo !== 'calculo'" class="block text-sm font-medium">Campo<input v-model="form.campo" required class="mt-1 w-full rounded border p-2" /></label><label v-if="form.tipo === 'formato'" class="block text-sm font-medium">Regex<input v-model="form.regex" required class="mt-1 w-full rounded border p-2" /></label><div v-if="form.tipo === 'intervalo'" class="grid grid-cols-2 gap-2"><label class="text-sm">Mínimo<input v-model.number="form.min" type="number" class="mt-1 w-full rounded border p-2" /></label><label class="text-sm">Máximo<input v-model.number="form.max" type="number" class="mt-1 w-full rounded border p-2" /></label></div><template v-if="form.tipo === 'calculo'"><label class="block text-sm font-medium">Expressão<input v-model="form.expressao" required class="mt-1 w-full rounded border p-2" /></label><label class="block text-sm font-medium">Campo resultado<input v-model="form.campo_resultado" required class="mt-1 w-full rounded border p-2" /></label></template><label class="flex gap-2 text-sm"><input v-model="form.obrigatoria" type="checkbox" /> Regra obrigatória</label><div class="flex justify-end gap-2"><BaseButton type="button" variant="secondary" @click="$emit('cancel')">Cancelar</BaseButton><BaseButton type="submit">Salvar regra</BaseButton></div></form></template>
